  // Must iterate and use classList on each li
  const iterates = /forEach|for\s*\(/.test(this.handlerBody);
  const usesClassList = new RegExp('classList\\.(toggle|add|remove)\\s*\\(\\s*['"]' + className + "['"]").test(this.handlerBody);
