+/**
+ * Find the body of an addEventListener callback in source.
+ * Uses brace matching starting after the function token.
+ */
+function findHandlerBody(source, searchPattern) {
+  // searchPattern is a regex that matches the addEventListener registration line
+  // e.g. /\.toggle['"]?\.addEventListener\(['"]click['"],\s*function\s*\(/
+  const lines = source.split('\n');
+  let startLine = -1;
+  for (let i = 0; i < lines.length; i++) {
+    if (searchPattern.test(lines[i])) {
+      startLine = i;
+      break;
+    }
+  }
+  if (startLine === -1) return null;
+
+  // Find the opening brace of the function body
+  let combined = '';
+  for (let i = startLine; i < lines.length; i++) {
+    combined += lines[i] + '\n';
+  }
+
+  // Find the function body: find the first '{' after 'function'
+  const funcMatch = combined.match(/function\s*\([^)]*\)\s*\{/);
+  if (!funcMatch) return null;
+
+  const bodyStart = funcMatch.index + funcMatch[0].length;
+  // Now walk forward counting braces
+  let depth = 1;
+  let pos = bodyStart;
+  while (depth > 0 && pos < combined.length) {
+    if (combined[pos] === '{') depth++;
+    else if (combined[pos] === '}') depth--;
+    pos++;
+  }
+  return combined.slice(bodyStart, pos - 1); // exclude final '}'
+}
